fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and switch to the 'Scheduling' application, landing on its 'Dashboard' left-nav section (the default). Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) scheduling-overview — confirm the scheduling overview renders: a System Health area (circular health-score ring) plus KPI cards such as 'Active Jobs', 'Due Next Hour', 'Runs (24h)', 'Running Now', and side panels titled 'Live Executions', 'Alerts'/'All Clear', and 'Upcoming (24h)' (empty panels with a 'No recent executions'/'No active alerts' state still count); (2) auto-refresh-toggle — in the header actions click the 'Auto: OFF'/'Auto: ON' button (circular-arrows icon) and confirm the label toggles between ON and OFF and the button's emphasis (primary vs secondary styling) changes accordingly (toggling once, ideally back, is enough). Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200/app/scheduling",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "scheduling-overview",
      "instruction": "the Scheduling Dashboard overview renders",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/scheduling"
        }
      ],
      "visualCriteria": [
        "The Dashboard shows a System Health ring and KPI cards (Active Jobs / Due Next Hour / Runs / Running Now), and the Live Executions, Alerts (or 'All Clear') and Upcoming panels render — populated rows or valid empty-state messages both acceptable"
      ]
    },
    {
      "name": "auto-refresh-toggle",
      "instruction": "toggle the Auto-Refresh button",
      "visualCriteria": [
        "An 'Auto:' toggle button is visible in the Dashboard header actions, and clicking it flips the label between 'Auto: ON' and 'Auto: OFF' and visibly changes the button's active/inactive styling"
      ]
    }
  ]
}
